insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (82, 5, 20, 37, 'سورة المائدة ٢٠ – ٣٧', 'ادخلوا الأرض المقدسة، وابنا آدم، و«من أحياها فكأنما أحيا الناس جميعاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 82) = $j$[{"lbl": "الآيات ٢٠ – ٢٣", "q": "وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَعَلَ فِيكُمۡ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكٗا وَءَاتَىٰكُم مَّا لَمۡ يُؤۡتِ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ ﴿٢٠﴾ يَٰقَوۡمِ ٱدۡخُلُواْ ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِي كَتَبَ ٱللَّهُ لَكُمۡ وَلَا تَرۡتَدُّواْ عَلَىٰٓ أَدۡبَارِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ ﴿٢١﴾ قَالُواْ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوۡمٗا جَبَّارِينَ وَإِنَّا لَن نَّدۡخُلَهَا حَتَّىٰ يَخۡرُجُواْ مِنۡهَا فَإِن يَخۡرُجُواْ مِنۡهَا فَإِنَّا دَٰخِلُونَ ﴿٢٢﴾ قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِمَا ٱدۡخُلُواْ عَلَيۡهِمُ ٱلۡبَابَ فَإِذَا دَخَلۡتُمُوهُ فَإِنَّكُمۡ غَٰلِبُونَۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓاْ إِن كُنتُم مُّؤۡمِنِينَ ﴿٢٣﴾", "w": [["نعمة الله عليكم", "منها نجاتهم من فرعون وملئه."], ["إذ جعل فيكم أنبياء", "منهم موسى وهارون ﵉."], ["وجعلكم ملوكاً", "مالكين أمر أنفسكم بعد الاستعباد الفرعوني."], ["العالمين", "المعاصرين لهم والسابقين."], ["الأرض المقدسة التي كتب الله لكم", "المطهّرة التي فرض الله عليكم دخولها والسكن فيها."], ["ولا ترتدّوا على أدباركم", "لا ترجعوا منهزمين إلى الوراء."], ["قوماً جبّارين", "عظام الأجسام أقوياء الأبدان، يجبرون على طاعتهم من شاؤوا."], ["يخافون", "مخالفة أمر الله ومعصية رسوله."], ["أنعم الله عليهما", "بنعمة العصمة، فلم يُفشيا سرّ ما شاهداه في أرض الجبّارين، وهما يوشع وكالب من النقباء."]], "m": "ما زال السياق في اليهود، فقال الله لرسوله ﷺ: واذكر إذ قال موسى لقومه: اذكروا نعمة الله عليكم إذ جعل فيكم أنبياء، وجعلكم ملوكاً تملكون أنفسكم، وآتاكم ما لم يؤتِ أحداً من العالمين، يا قوم ادخلوا الأرض المقدسة التي كتب الله لكم، فافتحوا باب المدينة وباغتوا العدو، ولا ترجعوا منهزمين فتنقلبوا خاسرين. فقالوا: يا موسى إن فيها قوماً جبّارين، وإنا لن ندخلها حتى يخرجوا منها؛ وكان سبب هذه الهزيمة الروحية ما أذاعه النقباء من أخبار مهولة عن العمالقة، إلا اثنين منهم: يوشع بن نون وكالب بن يوحنا، خافا الله فعصمهما من إفشاء ما رأيا إلا لموسى، فقالا للقوم: ادخلوا عليهم الباب، فإذا دخلتموه فإنكم غالبون، لعنصر المباغتة، وعلى الله فتوكلوا إن كنتم مؤمنين. وفي ذلك تسلية للرسول ﷺ ليزول استعظامه همّهم بقتله.", "h": ["تسلية الرسول ﷺ بإعلامه بخبث اليهود وشدة ضعفهم ومرض قلوبهم.", "فضح اليهود بكشف الآيات عن مخازيهم مع أنبيائهم.", "بيان الأثر السيئ الذي تركته إذاعة النقباء للأخبار الكاذبة المهولة، وقد استعملت ألمانيا النازية هذا الأسلوب ونجحت نجاحاً كبيراً حيث اجتاحت نصف أوربا في مدة قصيرة.", "بيان سنة الله تعالى أنه لا يخلو زمان ولا مكان من عبد صالح تقوم به الحجة.", "فائدة عنصر المباغتة في الحرب، وأنه عنصر فعّال في كسب الانتصار."], "k": "«قال رجلان من الذين يخافون أنعم الله عليهما»… هل أكون صوت الثبات حين يُرجف الناس، أم أنشر الخوف؟"}, {"lbl": "الآيات ٢٤ – ٢٦", "q": "قَالُواْ يَٰمُوسَىٰٓ إِنَّا لَن نَّدۡخُلَهَآ أَبَدٗا مَّا دَامُواْ فِيهَا فَٱذۡهَبۡ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ ﴿٢٤﴾ قَالَ رَبِّ إِنِّي لَآ أَمۡلِكُ إِلَّا نَفۡسِي وَأَخِيۖ فَٱفۡرُقۡ بَيۡنَنَا وَبَيۡنَ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ ﴿٢٥﴾ قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيۡهِمۡۛ أَرۡبَعِينَ سَنَةٗۛ يَتِيهُونَ فِي ٱلۡأَرۡضِۚ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ ﴿٢٦﴾", "w": [["الفاسقين", "الخارجين عن أمر الله ورسوله بتركهم الجهاد جبناً وخوفاً."], ["محرّمة عليهم", "تحريماً كونياً قضائياً، لا شرعياً تعبّدياً."], ["يتيهون في الأرض", "في أرض سيناء متحيّرين، لا يدرون أين يذهبون، مدة أربعين سنة."], ["فلا تأسَ", "لا تحزن ولا تتأسّف."]], "m": "هذا جواب القوم على الرجلين الصالحين، إذ قالوا بكل وقاحة: يا موسى إنا لن ندخلها أبداً ما داموا فيها، فاذهب أنت وربك فقاتلا إنا هاهنا قاعدون؛ فأيّ تمرّد وجبن وسوء أدب أعظم من هذا؟ فقال موسى متبرّئاً منهم: رب إني لا أملك إلا نفسي وأخي هارون، فافرق بيننا وبين القوم الفاسقين. فأجابه ربه: فإنها محرّمة عليهم أربعين سنة، فما دخلوها إلا بعد مضيّها، يتيهون في أرض سيناء متحيّرين لا يدرون أين يذهبون ولا من أين يأتون، فلا تأسَ على القوم الفاسقين، فهذا جزاؤهم عُجّل لهم.", "h": ["بيان جبن اليهود، وسوء أدبهم مع ربهم وأنبيائهم.", "وجوب البراءة من أهل الفسق ببغض عملهم، وتركهم لنقمة الله تنزل بهم.", "حرمة الحزن والتأسّف على الفاسقين والظالمين إذا حلّت بهم العقوبة الإلهية جزاء فسقهم وظلمهم."], "k": "«إنا هاهنا قاعدون»… في أي خير قعدتُ وانتظرت غيري أن يقوم به عني؟"}, {"lbl": "الآيات ٢٧ – ٣١", "q": "۞وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱبۡنَيۡ ءَادَمَ بِٱلۡحَقِّ إِذۡ قَرَّبَا قُرۡبَانٗا فَتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ يُتَقَبَّلۡ مِنَ ٱلۡأٓخَرِ قَالَ لَأَقۡتُلَنَّكَۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ ﴿٢٧﴾ لَئِنۢ بَسَطتَ إِلَيَّ يَدَكَ لِتَقۡتُلَنِي مَآ أَنَا۠ بِبَاسِطٖ يَدِيَ إِلَيۡكَ لِأَقۡتُلَكَۖ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ ﴿٢٨﴾ إِنِّيٓ أُرِيدُ أَن تَبُوٓأَ بِإِثۡمِي وَإِثۡمِكَ فَتَكُونَ مِنۡ أَصۡحَٰبِ ٱلنَّارِۚ وَذَٰلِكَ جَزَـٰٓؤُاْ ٱلظَّـٰلِمِينَ ﴿٢٩﴾ فَطَوَّعَتۡ لَهُۥ نَفۡسُهُۥ قَتۡلَ أَخِيهِ فَقَتَلَهُۥ فَأَصۡبَحَ مِنَ ٱلۡخَٰسِرِينَ ﴿٣٠﴾ فَبَعَثَ ٱللَّهُ غُرَابٗا يَبۡحَثُ فِي ٱلۡأَرۡضِ لِيُرِيَهُۥ كَيۡفَ يُوَٰرِي سَوۡءَةَ أَخِيهِۚ قَالَ يَٰوَيۡلَتَىٰٓ أَعَجَزۡتُ أَنۡ أَكُونَ مِثۡلَ هَٰذَا ٱلۡغُرَابِ فَأُوَٰرِيَ سَوۡءَةَ أَخِيۖ فَأَصۡبَحَ مِنَ ٱلنَّـٰدِمِينَ ﴿٣١﴾", "w": [["واتلُ عليهم", "واقرأ على اليهود الذين همّوا بقتلك وقتل أصحابك."], ["نبأ ابني آدم", "خبر ابني آدم: هابيل وقابيل."], ["قرباناً", "ما يُتقرّب به إلى الله تعالى كالصلاة والصدقات."], ["بسطت إليّ يدك", "مددت إليّ يدك."], ["أن تبوء بإثمي وإثمك", "ترجع إلى الله يوم القيامة بإثم قتلك إياي، وإثمك في معاصيك."], ["فطوّعت له نفسه", "شجّعته على القتل وزيّنته له حتى فعله."], ["غراباً", "طائراً أسود معروفاً."], ["يواري سوأة أخيه", "يستر بالتراب جسد أخيه، والسوأة ما يُكره النظر إليه."]], "m": "ما زال السياق في يهود بني النضير الذين همّوا بقتل النبي ﷺ، فقال تعالى لرسوله: اقرأ عليهم قصة ابني آدم ليعلموا عاقبة جريمة القتل التي همّوا بها، إذ قرّبا قرباناً، فتُقبّل من هابيل لأنه كان من أحسن ماله ونفسه به طيبة، ولم يُتقبّل من قابيل لأنه كان من أردأ ماله، فقال لأخيه حسداً: لأقتلنّك، كما حسدك اليهود على النبوة. فقال له أخوه: إنما يتقبّل الله من المتقين، فلو أخلصت لتُقبّل منك، والله لئن بسطت إليّ يدك لتقتلني ما أنا بباسط يدي إليك لأقتلك، إني أخاف الله رب العالمين، أن ألقاه بدم أرقته ظلماً، إني أريد أن تبوء بإثمي وإثمك فتكون من أصحاب النار، وذلك جزاء الظالمين. فزيّنت له نفسه قتل أخيه فقتله فأصبح من الخاسرين، وحمله على عاتقه لا يدري ما يصنع به حتى أنتن، فبعث الله غراباً ينبش الأرض ويواري غراباً ميتاً، ليريه كيف يواري سوأة أخيه، فقال متحسّراً: يا ويلتا أعجزت أن أكون مثل هذا الغراب فأواري سوأة أخي؟ فأصبح من النادمين، ومجرد الندم لا يكون توبة.", "h": ["مشروعية التقرّب إلى الله تعالى بما يحب أن يُتقرّب به إليه.", "عظم جريمة الحسد، وما يترتب عليها من الآثار السيئة.", "قبول الأعمال الصالحة يتوقف على الإخلاص فيها لله تعالى.", "بيان أول من سنّ جريمة القتل، وهو قابيل، ولذا ورد: «ما من نفس تُقتل ظلماً إلا كان على ابن آدم الأول كِفل منها، لأنه أول من سنّ القتل».", "مشروعية الدفن، وبيان زمنه.", "خير ابني آدم المقتول ظلماً، وشرّهما القاتل ظلماً."], "k": "«إنما يتقبّل الله من المتقين»… هل أعطي لله من أحسن ما عندي، أم من فُضول ما لا أحتاجه؟"}, {"lbl": "الآية ٣٢", "q": "مِنۡ أَجۡلِ ذَٰلِكَ كَتَبۡنَا عَلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفۡسَۢا بِغَيۡرِ نَفۡسٍ أَوۡ فَسَادٖ فِي ٱلۡأَرۡضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعٗا وَمَنۡ أَحۡيَاهَا فَكَأَنَّمَآ أَحۡيَا ٱلنَّاسَ جَمِيعٗاۚ وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُنَا بِٱلۡبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرٗا مِّنۡهُم بَعۡدَ ذَٰلِكَ فِي ٱلۡأَرۡضِ لَمُسۡرِفُونَ ﴿٣٢﴾", "w": [["من أجل ذلك", "بسبب ذلك القتل."], ["كتبنا", "أوحينا."], ["أو فساد في الأرض", "بحربه لله ورسوله والمؤمنين."], ["ومن أحياها", "قدر على قتلها وهي مستوجبة له فتركها."], ["بالبيّنات", "الآيات الواضحات الحاملة للشرائع والدلائل."], ["مسرفون", "مكثرون من المعاصي والذنوب."]], "m": "من أجل قبح جريمة القتل وما يترتب عليها من مفاسد، شدّد الله على بني إسرائيل لكثرة ما شاع بينهم من سفك الدماء، فقد قتلوا زكريا ويحيى، وهمّوا بقتل عيسى ومحمد ﷺ: أنه من قتل نفساً بغير نفس، أو بغير فساد في الأرض بحرب الله ورسوله والمؤمنين، فكأنما قتل الناس جميعاً، بمعنى يُعذّب عذاب من قتل الناس جميعاً، ومن أحياها بأن عفا عنها وقد استوجبت القتل فكأنما أحيا الناس جميعاً، فيُعطى أجر ذلك، تنفيراً لهم من القتل وترغيباً في العفو. ولقد جاءتهم رسلهم بالبيّنات، فلم يكن شرّهم عن جهل، بل هم قوم متمرّدون، ثم إن كثيراً منهم بعد ذلك في الأرض لمسرفون. وبهذا انتهى الحديث عن اليهود المتعلق بهمّهم بقتل الرسول ﷺ وأصحابه، تسليةً له ولكل مؤمن يتعرّض لمكرهم.", "h": ["تأديب الرب تعالى لبني إسرائيل، ومع الأسف لم ينتفعوا به.", "فساد بني إسرائيل لم ينشأ عن الجهل وقلة العلم، بل كان اتباعاً للأهواء وجرياً وراء عرض الدنيا، فلذا غضب الله عليهم ولعنهم لأنهم عالمون.", "بالرغم من تضعيف جزاء الجريمة على اليهود ومضاعفة أجر الحسنة لهم، فإنهم أكثر الناس إسرافاً في الشر والفساد في الأرض."], "k": "«ومن أحياها فكأنما أحيا الناس جميعاً»… هل أستطيع اليوم أن «أحيي» نفساً: بإنقاذ، أو عفو، أو مساعدة مريض؟"}, {"lbl": "الآيتان ٣٣ – ٣٤", "q": "إِنَّمَا جَزَـٰٓؤُاْ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادًا أَن يُقَتَّلُوٓاْ أَوۡ يُصَلَّبُوٓاْ أَوۡ تُقَطَّعَ أَيۡدِيهِمۡ وَأَرۡجُلُهُم مِّنۡ خِلَٰفٍ أَوۡ يُنفَوۡاْ مِنَ ٱلۡأَرۡضِۚ ذَٰلِكَ لَهُمۡ خِزۡيٞ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٌ ﴿٣٣﴾ إِلَّا ٱلَّذِينَ تَابُواْ مِن قَبۡلِ أَن تَقۡدِرُواْ عَلَيۡهِمۡۖ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٣٤﴾", "w": [["يحاربون الله ورسوله", "بالخروج عن طاعتهما، وحمل السلاح على المؤمنين وقتلهم وسلب أموالهم."], ["ويسعون في الأرض فساداً", "بإخافة الناس وقطع طرقهم وسلب أموالهم والاعتداء على حرماتهم."], ["أو يُصلّبوا", "يُشدّون على أعواد الخشب بعد أن يُقتلوا."], ["من خلاف", "بأن تُقطع اليد اليمنى والرجل اليسرى، أو العكس."], ["أو يُنفوا من الأرض", "من أرض الإسلام."], ["خزي في الدنيا", "ذلّ ومهانة."], ["عذاب عظيم", "عذاب جهنم."]], "m": "لما ذكر الله ما أوجبه على اليهود من شدة العقوبة على القتل والفساد، ذكر حكم من يحارب المسلمين ويسعى بالفساد في ديارهم: إنما جزاء الذين يحاربون الله ورسوله بالقتل والسلب، ويسعون في الأرض فساداً بتخويف المسلمين وقطع طرقهم وأخذ أموالهم والاعتداء على أعراضهم، أن يُقتّلوا، أو يُصلّبوا بعد القتل مدة، أو تُقطّع أيديهم وأرجلهم من خلاف، أو يُنفوا من دار الإسلام أو يُحبسوا حتى ينجو المسلمون من شرّهم، ذلك لهم خزي في الدنيا، ولهم في الآخرة عذاب عظيم. إلا الذين تابوا من قبل أن تقدروا عليهم، فجاؤوا تائبين، فاعلموا أن الله غفور رحيم: فإن كان كافراً فأسلم فالإسلام يجُبّ ما قبله، وإن كان مسلماً سقط عنه حدّ الحرابة ووجب عليه ردّ المال إن بقي في يده.", "h": ["بيان حكم الحرابة وحقيقتها: خروج جماعة لهم شوكة وبأيديهم سلاح، بعيداً عن المدن، يشنّون هجمات على المسلمين فيقتلون ويسلبون ويعتدون على الأعراض.", "الإمام مخيّر في إنزال العقوبة التي يرى أنها مناسبة لاستتباب الأمن.", "من تاب من المحاربين قبل التمكّن منه عُفي عنه، إلا أن يكون بيده مال سلبه فيردّه على ذويه.", "عظم عفو الله ورحمته بعباده، لمغفرته لمن تاب ورحمته له."], "k": "أمن الناس على أنفسهم وأموالهم عند الله عظيم… فهل يأمن الناس من لساني ويدي؟"}, {"lbl": "الآيات ٣٥ – ٣٧", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَٱبۡتَغُوٓاْ إِلَيۡهِ ٱلۡوَسِيلَةَ وَجَٰهِدُواْ فِي سَبِيلِهِۦ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿٣٥﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ لَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لِيَفۡتَدُواْ بِهِۦ مِنۡ عَذَابِ يَوۡمِ ٱلۡقِيَٰمَةِ مَا تُقُبِّلَ مِنۡهُمۡۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿٣٦﴾ يُرِيدُونَ أَن يَخۡرُجُواْ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنۡهَاۖ وَلَهُمۡ عَذَابٞ مُّقِيمٞ ﴿٣٧﴾", "w": [["اتقوا الله", "خافوا عذابه، فامتثلوا أمره وأمر رسوله واجتنبوا نهيهما."], ["وابتغوا", "اطلبوا."], ["الوسيلة", "تقرّبوا إليه بفعل محابّه وترك مساخطه تظفروا بالقرب منه."], ["وجاهدوا في سبيله", "جاهدوا أنفسكم بحملها على أن تتعلم وتعمل وتعلّم، وأعداءه بدعوتهم إلى الإسلام."], ["تفلحون", "تنجون من النار وتدخلون الجنة."], ["عذاب مقيم", "دائم لا يزول."]], "m": "ينادي الله عباده المؤمنين ليرشدهم إلى ما ينجيهم من العذاب وما يدنيهم من الرحمة: اتقوا الله، فإن عذابه لا يُتّقى إلا بالتقوى، وابتغوا إليه الوسيلة، أي تقرّبوا إليه بفعل ما يحب وترك ما يكره تفوزوا بالقرب منه، وجاهدوا في سبيله أنفسكم في طاعته، والشيطان في معصيته، والكفار في دعوتهم إلى الإسلام، باذلين كل ما في وسعكم، لعلكم تفلحون. ثم علّل ذلك بأن العذاب الذي أُمروا باتقائه لا يُطاق: فلو أن للذين كفروا ما في الأرض جميعاً ومثله معه ليفتدوا به من عذاب يوم القيامة ما تُقبّل منهم، ولهم عذاب أليم، يتمنّون بكل قلوبهم أن يخرجوا من النار وما هم بخارجين منها، ولهم عذاب مقيم.", "h": ["وجوب تقوى الله عز وجل، وطلب القربة إليه، والجهاد في سبيله.", "مشروعية التوسّل إلى الله تعالى بالإيمان وصالح الأعمال.", "عظم عذاب يوم القيامة وشدته غير المتناهية.", "لا فدية يوم القيامة، ولا شفاعة تنفع الكافر فيخرج بها من النار.", "حسن التعليل للأمر والنهي، بما يشجّع على الامتثال والترك."], "k": "«وابتغوا إليه الوسيلة»… ما العمل الذي أتقرّب به إلى الله اليوم، وأرجو أن يكون وسيلتي إليه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 82;
insert into public.tdb_cards(topic, i, body) select 82, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٠ – ٢٣", "q": "وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَعَلَ فِيكُمۡ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكٗا وَءَاتَىٰكُم مَّا لَمۡ يُؤۡتِ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ ﴿٢٠﴾ يَٰقَوۡمِ ٱدۡخُلُواْ ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِي كَتَبَ ٱللَّهُ لَكُمۡ وَلَا تَرۡتَدُّواْ عَلَىٰٓ أَدۡبَارِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ ﴿٢١﴾ قَالُواْ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوۡمٗا جَبَّارِينَ وَإِنَّا لَن نَّدۡخُلَهَا حَتَّىٰ يَخۡرُجُواْ مِنۡهَا فَإِن يَخۡرُجُواْ مِنۡهَا فَإِنَّا دَٰخِلُونَ ﴿٢٢﴾ قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِمَا ٱدۡخُلُواْ عَلَيۡهِمُ ٱلۡبَابَ فَإِذَا دَخَلۡتُمُوهُ فَإِنَّكُمۡ غَٰلِبُونَۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓاْ إِن كُنتُم مُّؤۡمِنِينَ ﴿٢٣﴾", "w": [["نعمة الله عليكم", "منها نجاتهم من فرعون وملئه."], ["إذ جعل فيكم أنبياء", "منهم موسى وهارون ﵉."], ["وجعلكم ملوكاً", "مالكين أمر أنفسكم بعد الاستعباد الفرعوني."], ["العالمين", "المعاصرين لهم والسابقين."], ["الأرض المقدسة التي كتب الله لكم", "المطهّرة التي فرض الله عليكم دخولها والسكن فيها."], ["ولا ترتدّوا على أدباركم", "لا ترجعوا منهزمين إلى الوراء."], ["قوماً جبّارين", "عظام الأجسام أقوياء الأبدان، يجبرون على طاعتهم من شاؤوا."], ["يخافون", "مخالفة أمر الله ومعصية رسوله."], ["أنعم الله عليهما", "بنعمة العصمة، فلم يُفشيا سرّ ما شاهداه في أرض الجبّارين، وهما يوشع وكالب من النقباء."]], "m": "ما زال السياق في اليهود، فقال الله لرسوله ﷺ: واذكر إذ قال موسى لقومه: اذكروا نعمة الله عليكم إذ جعل فيكم أنبياء، وجعلكم ملوكاً تملكون أنفسكم، وآتاكم ما لم يؤتِ أحداً من العالمين، يا قوم ادخلوا الأرض المقدسة التي كتب الله لكم، فافتحوا باب المدينة وباغتوا العدو، ولا ترجعوا منهزمين فتنقلبوا خاسرين. فقالوا: يا موسى إن فيها قوماً جبّارين، وإنا لن ندخلها حتى يخرجوا منها؛ وكان سبب هذه الهزيمة الروحية ما أذاعه النقباء من أخبار مهولة عن العمالقة، إلا اثنين منهم: يوشع بن نون وكالب بن يوحنا، خافا الله فعصمهما من إفشاء ما رأيا إلا لموسى، فقالا للقوم: ادخلوا عليهم الباب، فإذا دخلتموه فإنكم غالبون، لعنصر المباغتة، وعلى الله فتوكلوا إن كنتم مؤمنين. وفي ذلك تسلية للرسول ﷺ ليزول استعظامه همّهم بقتله.", "h": ["تسلية الرسول ﷺ بإعلامه بخبث اليهود وشدة ضعفهم ومرض قلوبهم.", "فضح اليهود بكشف الآيات عن مخازيهم مع أنبيائهم.", "بيان الأثر السيئ الذي تركته إذاعة النقباء للأخبار الكاذبة المهولة، وقد استعملت ألمانيا النازية هذا الأسلوب ونجحت نجاحاً كبيراً حيث اجتاحت نصف أوربا في مدة قصيرة.", "بيان سنة الله تعالى أنه لا يخلو زمان ولا مكان من عبد صالح تقوم به الحجة.", "فائدة عنصر المباغتة في الحرب، وأنه عنصر فعّال في كسب الانتصار."], "k": "«قال رجلان من الذين يخافون أنعم الله عليهما»… هل أكون صوت الثبات حين يُرجف الناس، أم أنشر الخوف؟"}, {"lbl": "الآيات ٢٤ – ٢٦", "q": "قَالُواْ يَٰمُوسَىٰٓ إِنَّا لَن نَّدۡخُلَهَآ أَبَدٗا مَّا دَامُواْ فِيهَا فَٱذۡهَبۡ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ ﴿٢٤﴾ قَالَ رَبِّ إِنِّي لَآ أَمۡلِكُ إِلَّا نَفۡسِي وَأَخِيۖ فَٱفۡرُقۡ بَيۡنَنَا وَبَيۡنَ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ ﴿٢٥﴾ قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيۡهِمۡۛ أَرۡبَعِينَ سَنَةٗۛ يَتِيهُونَ فِي ٱلۡأَرۡضِۚ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ ﴿٢٦﴾", "w": [["الفاسقين", "الخارجين عن أمر الله ورسوله بتركهم الجهاد جبناً وخوفاً."], ["محرّمة عليهم", "تحريماً كونياً قضائياً، لا شرعياً تعبّدياً."], ["يتيهون في الأرض", "في أرض سيناء متحيّرين، لا يدرون أين يذهبون، مدة أربعين سنة."], ["فلا تأسَ", "لا تحزن ولا تتأسّف."]], "m": "هذا جواب القوم على الرجلين الصالحين، إذ قالوا بكل وقاحة: يا موسى إنا لن ندخلها أبداً ما داموا فيها، فاذهب أنت وربك فقاتلا إنا هاهنا قاعدون؛ فأيّ تمرّد وجبن وسوء أدب أعظم من هذا؟ فقال موسى متبرّئاً منهم: رب إني لا أملك إلا نفسي وأخي هارون، فافرق بيننا وبين القوم الفاسقين. فأجابه ربه: فإنها محرّمة عليهم أربعين سنة، فما دخلوها إلا بعد مضيّها، يتيهون في أرض سيناء متحيّرين لا يدرون أين يذهبون ولا من أين يأتون، فلا تأسَ على القوم الفاسقين، فهذا جزاؤهم عُجّل لهم.", "h": ["بيان جبن اليهود، وسوء أدبهم مع ربهم وأنبيائهم.", "وجوب البراءة من أهل الفسق ببغض عملهم، وتركهم لنقمة الله تنزل بهم.", "حرمة الحزن والتأسّف على الفاسقين والظالمين إذا حلّت بهم العقوبة الإلهية جزاء فسقهم وظلمهم."], "k": "«إنا هاهنا قاعدون»… في أي خير قعدتُ وانتظرت غيري أن يقوم به عني؟"}, {"lbl": "الآيات ٢٧ – ٣١", "q": "۞وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱبۡنَيۡ ءَادَمَ بِٱلۡحَقِّ إِذۡ قَرَّبَا قُرۡبَانٗا فَتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ يُتَقَبَّلۡ مِنَ ٱلۡأٓخَرِ قَالَ لَأَقۡتُلَنَّكَۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ ﴿٢٧﴾ لَئِنۢ بَسَطتَ إِلَيَّ يَدَكَ لِتَقۡتُلَنِي مَآ أَنَا۠ بِبَاسِطٖ يَدِيَ إِلَيۡكَ لِأَقۡتُلَكَۖ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ ﴿٢٨﴾ إِنِّيٓ أُرِيدُ أَن تَبُوٓأَ بِإِثۡمِي وَإِثۡمِكَ فَتَكُونَ مِنۡ أَصۡحَٰبِ ٱلنَّارِۚ وَذَٰلِكَ جَزَـٰٓؤُاْ ٱلظَّـٰلِمِينَ ﴿٢٩﴾ فَطَوَّعَتۡ لَهُۥ نَفۡسُهُۥ قَتۡلَ أَخِيهِ فَقَتَلَهُۥ فَأَصۡبَحَ مِنَ ٱلۡخَٰسِرِينَ ﴿٣٠﴾ فَبَعَثَ ٱللَّهُ غُرَابٗا يَبۡحَثُ فِي ٱلۡأَرۡضِ لِيُرِيَهُۥ كَيۡفَ يُوَٰرِي سَوۡءَةَ أَخِيهِۚ قَالَ يَٰوَيۡلَتَىٰٓ أَعَجَزۡتُ أَنۡ أَكُونَ مِثۡلَ هَٰذَا ٱلۡغُرَابِ فَأُوَٰرِيَ سَوۡءَةَ أَخِيۖ فَأَصۡبَحَ مِنَ ٱلنَّـٰدِمِينَ ﴿٣١﴾", "w": [["واتلُ عليهم", "واقرأ على اليهود الذين همّوا بقتلك وقتل أصحابك."], ["نبأ ابني آدم", "خبر ابني آدم: هابيل وقابيل."], ["قرباناً", "ما يُتقرّب به إلى الله تعالى كالصلاة والصدقات."], ["بسطت إليّ يدك", "مددت إليّ يدك."], ["أن تبوء بإثمي وإثمك", "ترجع إلى الله يوم القيامة بإثم قتلك إياي، وإثمك في معاصيك."], ["فطوّعت له نفسه", "شجّعته على القتل وزيّنته له حتى فعله."], ["غراباً", "طائراً أسود معروفاً."], ["يواري سوأة أخيه", "يستر بالتراب جسد أخيه، والسوأة ما يُكره النظر إليه."]], "m": "ما زال السياق في يهود بني النضير الذين همّوا بقتل النبي ﷺ، فقال تعالى لرسوله: اقرأ عليهم قصة ابني آدم ليعلموا عاقبة جريمة القتل التي همّوا بها، إذ قرّبا قرباناً، فتُقبّل من هابيل لأنه كان من أحسن ماله ونفسه به طيبة، ولم يُتقبّل من قابيل لأنه كان من أردأ ماله، فقال لأخيه حسداً: لأقتلنّك، كما حسدك اليهود على النبوة. فقال له أخوه: إنما يتقبّل الله من المتقين، فلو أخلصت لتُقبّل منك، والله لئن بسطت إليّ يدك لتقتلني ما أنا بباسط يدي إليك لأقتلك، إني أخاف الله رب العالمين، أن ألقاه بدم أرقته ظلماً، إني أريد أن تبوء بإثمي وإثمك فتكون من أصحاب النار، وذلك جزاء الظالمين. فزيّنت له نفسه قتل أخيه فقتله فأصبح من الخاسرين، وحمله على عاتقه لا يدري ما يصنع به حتى أنتن، فبعث الله غراباً ينبش الأرض ويواري غراباً ميتاً، ليريه كيف يواري سوأة أخيه، فقال متحسّراً: يا ويلتا أعجزت أن أكون مثل هذا الغراب فأواري سوأة أخي؟ فأصبح من النادمين، ومجرد الندم لا يكون توبة.", "h": ["مشروعية التقرّب إلى الله تعالى بما يحب أن يُتقرّب به إليه.", "عظم جريمة الحسد، وما يترتب عليها من الآثار السيئة.", "قبول الأعمال الصالحة يتوقف على الإخلاص فيها لله تعالى.", "بيان أول من سنّ جريمة القتل، وهو قابيل، ولذا ورد: «ما من نفس تُقتل ظلماً إلا كان على ابن آدم الأول كِفل منها، لأنه أول من سنّ القتل».", "مشروعية الدفن، وبيان زمنه.", "خير ابني آدم المقتول ظلماً، وشرّهما القاتل ظلماً."], "k": "«إنما يتقبّل الله من المتقين»… هل أعطي لله من أحسن ما عندي، أم من فُضول ما لا أحتاجه؟"}, {"lbl": "الآية ٣٢", "q": "مِنۡ أَجۡلِ ذَٰلِكَ كَتَبۡنَا عَلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفۡسَۢا بِغَيۡرِ نَفۡسٍ أَوۡ فَسَادٖ فِي ٱلۡأَرۡضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعٗا وَمَنۡ أَحۡيَاهَا فَكَأَنَّمَآ أَحۡيَا ٱلنَّاسَ جَمِيعٗاۚ وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُنَا بِٱلۡبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرٗا مِّنۡهُم بَعۡدَ ذَٰلِكَ فِي ٱلۡأَرۡضِ لَمُسۡرِفُونَ ﴿٣٢﴾", "w": [["من أجل ذلك", "بسبب ذلك القتل."], ["كتبنا", "أوحينا."], ["أو فساد في الأرض", "بحربه لله ورسوله والمؤمنين."], ["ومن أحياها", "قدر على قتلها وهي مستوجبة له فتركها."], ["بالبيّنات", "الآيات الواضحات الحاملة للشرائع والدلائل."], ["مسرفون", "مكثرون من المعاصي والذنوب."]], "m": "من أجل قبح جريمة القتل وما يترتب عليها من مفاسد، شدّد الله على بني إسرائيل لكثرة ما شاع بينهم من سفك الدماء، فقد قتلوا زكريا ويحيى، وهمّوا بقتل عيسى ومحمد ﷺ: أنه من قتل نفساً بغير نفس، أو بغير فساد في الأرض بحرب الله ورسوله والمؤمنين، فكأنما قتل الناس جميعاً، بمعنى يُعذّب عذاب من قتل الناس جميعاً، ومن أحياها بأن عفا عنها وقد استوجبت القتل فكأنما أحيا الناس جميعاً، فيُعطى أجر ذلك، تنفيراً لهم من القتل وترغيباً في العفو. ولقد جاءتهم رسلهم بالبيّنات، فلم يكن شرّهم عن جهل، بل هم قوم متمرّدون، ثم إن كثيراً منهم بعد ذلك في الأرض لمسرفون. وبهذا انتهى الحديث عن اليهود المتعلق بهمّهم بقتل الرسول ﷺ وأصحابه، تسليةً له ولكل مؤمن يتعرّض لمكرهم.", "h": ["تأديب الرب تعالى لبني إسرائيل، ومع الأسف لم ينتفعوا به.", "فساد بني إسرائيل لم ينشأ عن الجهل وقلة العلم، بل كان اتباعاً للأهواء وجرياً وراء عرض الدنيا، فلذا غضب الله عليهم ولعنهم لأنهم عالمون.", "بالرغم من تضعيف جزاء الجريمة على اليهود ومضاعفة أجر الحسنة لهم، فإنهم أكثر الناس إسرافاً في الشر والفساد في الأرض."], "k": "«ومن أحياها فكأنما أحيا الناس جميعاً»… هل أستطيع اليوم أن «أحيي» نفساً: بإنقاذ، أو عفو، أو مساعدة مريض؟"}, {"lbl": "الآيتان ٣٣ – ٣٤", "q": "إِنَّمَا جَزَـٰٓؤُاْ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادًا أَن يُقَتَّلُوٓاْ أَوۡ يُصَلَّبُوٓاْ أَوۡ تُقَطَّعَ أَيۡدِيهِمۡ وَأَرۡجُلُهُم مِّنۡ خِلَٰفٍ أَوۡ يُنفَوۡاْ مِنَ ٱلۡأَرۡضِۚ ذَٰلِكَ لَهُمۡ خِزۡيٞ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٌ ﴿٣٣﴾ إِلَّا ٱلَّذِينَ تَابُواْ مِن قَبۡلِ أَن تَقۡدِرُواْ عَلَيۡهِمۡۖ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٣٤﴾", "w": [["يحاربون الله ورسوله", "بالخروج عن طاعتهما، وحمل السلاح على المؤمنين وقتلهم وسلب أموالهم."], ["ويسعون في الأرض فساداً", "بإخافة الناس وقطع طرقهم وسلب أموالهم والاعتداء على حرماتهم."], ["أو يُصلّبوا", "يُشدّون على أعواد الخشب بعد أن يُقتلوا."], ["من خلاف", "بأن تُقطع اليد اليمنى والرجل اليسرى، أو العكس."], ["أو يُنفوا من الأرض", "من أرض الإسلام."], ["خزي في الدنيا", "ذلّ ومهانة."], ["عذاب عظيم", "عذاب جهنم."]], "m": "لما ذكر الله ما أوجبه على اليهود من شدة العقوبة على القتل والفساد، ذكر حكم من يحارب المسلمين ويسعى بالفساد في ديارهم: إنما جزاء الذين يحاربون الله ورسوله بالقتل والسلب، ويسعون في الأرض فساداً بتخويف المسلمين وقطع طرقهم وأخذ أموالهم والاعتداء على أعراضهم، أن يُقتّلوا، أو يُصلّبوا بعد القتل مدة، أو تُقطّع أيديهم وأرجلهم من خلاف، أو يُنفوا من دار الإسلام أو يُحبسوا حتى ينجو المسلمون من شرّهم، ذلك لهم خزي في الدنيا، ولهم في الآخرة عذاب عظيم. إلا الذين تابوا من قبل أن تقدروا عليهم، فجاؤوا تائبين، فاعلموا أن الله غفور رحيم: فإن كان كافراً فأسلم فالإسلام يجُبّ ما قبله، وإن كان مسلماً سقط عنه حدّ الحرابة ووجب عليه ردّ المال إن بقي في يده.", "h": ["بيان حكم الحرابة وحقيقتها: خروج جماعة لهم شوكة وبأيديهم سلاح، بعيداً عن المدن، يشنّون هجمات على المسلمين فيقتلون ويسلبون ويعتدون على الأعراض.", "الإمام مخيّر في إنزال العقوبة التي يرى أنها مناسبة لاستتباب الأمن.", "من تاب من المحاربين قبل التمكّن منه عُفي عنه، إلا أن يكون بيده مال سلبه فيردّه على ذويه.", "عظم عفو الله ورحمته بعباده، لمغفرته لمن تاب ورحمته له."], "k": "أمن الناس على أنفسهم وأموالهم عند الله عظيم… فهل يأمن الناس من لساني ويدي؟"}, {"lbl": "الآيات ٣٥ – ٣٧", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَٱبۡتَغُوٓاْ إِلَيۡهِ ٱلۡوَسِيلَةَ وَجَٰهِدُواْ فِي سَبِيلِهِۦ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿٣٥﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ لَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لِيَفۡتَدُواْ بِهِۦ مِنۡ عَذَابِ يَوۡمِ ٱلۡقِيَٰمَةِ مَا تُقُبِّلَ مِنۡهُمۡۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿٣٦﴾ يُرِيدُونَ أَن يَخۡرُجُواْ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنۡهَاۖ وَلَهُمۡ عَذَابٞ مُّقِيمٞ ﴿٣٧﴾", "w": [["اتقوا الله", "خافوا عذابه، فامتثلوا أمره وأمر رسوله واجتنبوا نهيهما."], ["وابتغوا", "اطلبوا."], ["الوسيلة", "تقرّبوا إليه بفعل محابّه وترك مساخطه تظفروا بالقرب منه."], ["وجاهدوا في سبيله", "جاهدوا أنفسكم بحملها على أن تتعلم وتعمل وتعلّم، وأعداءه بدعوتهم إلى الإسلام."], ["تفلحون", "تنجون من النار وتدخلون الجنة."], ["عذاب مقيم", "دائم لا يزول."]], "m": "ينادي الله عباده المؤمنين ليرشدهم إلى ما ينجيهم من العذاب وما يدنيهم من الرحمة: اتقوا الله، فإن عذابه لا يُتّقى إلا بالتقوى، وابتغوا إليه الوسيلة، أي تقرّبوا إليه بفعل ما يحب وترك ما يكره تفوزوا بالقرب منه، وجاهدوا في سبيله أنفسكم في طاعته، والشيطان في معصيته، والكفار في دعوتهم إلى الإسلام، باذلين كل ما في وسعكم، لعلكم تفلحون. ثم علّل ذلك بأن العذاب الذي أُمروا باتقائه لا يُطاق: فلو أن للذين كفروا ما في الأرض جميعاً ومثله معه ليفتدوا به من عذاب يوم القيامة ما تُقبّل منهم، ولهم عذاب أليم، يتمنّون بكل قلوبهم أن يخرجوا من النار وما هم بخارجين منها، ولهم عذاب مقيم.", "h": ["وجوب تقوى الله عز وجل، وطلب القربة إليه، والجهاد في سبيله.", "مشروعية التوسّل إلى الله تعالى بالإيمان وصالح الأعمال.", "عظم عذاب يوم القيامة وشدته غير المتناهية.", "لا فدية يوم القيامة، ولا شفاعة تنفع الكافر فيخرج بها من النار.", "حسن التعليل للأمر والنهي، بما يشجّع على الامتثال والترك."], "k": "«وابتغوا إليه الوسيلة»… ما العمل الذي أتقرّب به إلى الله اليوم، وأرجو أن يكون وسيلتي إليه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (84, 5, 51, 66, 'سورة المائدة ٥١ – ٦٦', 'لا تتخذوا اليهود والنصارى أولياء، و«يحبهم ويحبونه»، و«بل يداه مبسوطتان»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 84) = $j$[{"lbl": "الآيات ٥١ – ٥٣", "q": "۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوۡلِيَآءَۘ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿٥١﴾ فَتَرَى ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ يُسَٰرِعُونَ فِيهِمۡ يَقُولُونَ نَخۡشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٞۚ فَعَسَى ٱللَّهُ أَن يَأۡتِيَ بِٱلۡفَتۡحِ أَوۡ أَمۡرٖ مِّنۡ عِندِهِۦ فَيُصۡبِحُواْ عَلَىٰ مَآ أَسَرُّواْ فِيٓ أَنفُسِهِمۡ نَٰدِمِينَ ﴿٥٢﴾ وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓاْ أَهَـٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ إِنَّهُمۡ لَمَعَكُمۡۚ حَبِطَتۡ أَعۡمَٰلُهُمۡ فَأَصۡبَحُواْ خَٰسِرِينَ ﴿٥٣﴾", "w": [["آمنوا", "صدّقوا بالله ورسوله ووعد الله ووعيده."], ["أولياء", "توالونهم بالنصرة والمحبة."], ["بعضهم أولياء بعض", "اليهودي ولي أخيه اليهودي، والنصراني ولي أخيه النصراني."], ["الظالمين", "الذين يوالون أعداء الله ورسوله ويتركون موالاة الله ورسوله."], ["مرض", "نفاق وشك وشرك."], ["يسارعون فيهم", "في البقاء على موالاتهم."], ["دائرة", "تدور علينا من جدب أو انتهاء أمر الإسلام."], ["بالفتح", "نصر المؤمنين على الكافرين، كفتح مكة."], ["جهد أيمانهم", "أقصاها وأبلغها."], ["حبطت أعمالهم", "بطلت وفسدت فلم ينتفعوا منها بشيء، لأنها ما كانت لله تعالى."]], "m": "ورد في سبب نزولها أن عبادة بن الصامت الأنصاري وعبد الله بن أُبيّ كان لهما حلفاء من اليهود، فلما أعلن اليهود سوء نياتهم تبرّأ عبادة من حلفائه ورضي بموالاة الله ورسوله والمؤمنين، وأبى ابن أُبيّ ذلك، فنزلت: يا أيها الذين آمنوا لا تتخذوا اليهود والنصارى أولياء، بعضهم أولياء بعض على المسلمين، فكيف تجوز موالاتهم؟ ومن يتولّهم منكم فإنه منهم، لأنه بحكم موالاتهم سيكون حرباً على الله ورسوله والمؤمنين، إن الله لا يهدي القوم الظالمين الذين وضعوا الموالاة في غير محلها. ثم قال لرسوله: فترى الذين في قلوبهم مرض، كابن أُبيّ، يسارعون في موالاتهم، يقولون: نخشى أن تصيبنا دائرة من تقلّب الأحوال فننتفع بأحلافنا، فعسى الله أن يأتي بالفتح، وعسى من الله للتحقيق، أو أمر من عنده فيصبحوا على ما أسرّوا في أنفسهم من النفاق نادمين. ويقول الذين آمنوا عند الفتح، مشيرين إلى المنافقين: أهؤلاء الذين أقسموا بالله جهد أيمانهم إنهم لمعكم؟ حبطت أعمالهم فأصبحوا خاسرين.", "h": ["حرمة موالاة اليهود والنصارى وسائر الكافرين.", "موالاة الكافر على المؤمن تُعتبر ردّة عن الإسلام.", "موالاة الكافرين ناجمة عن ضعف الإيمان، فلذا تؤدي إلى الكفر.", "عاقبة النفاق سيئة، ونهاية الكفر مريرة."], "k": "لمن ولائي ومحبتي ونصرتي؟ وهل يقدّمني ولائي يوم القيامة أم يُخجلني؟"}, {"lbl": "الآيات ٥٤ – ٥٦", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَن يَرۡتَدَّ مِنكُمۡ عَن دِينِهِۦ فَسَوۡفَ يَأۡتِي ٱللَّهُ بِقَوۡمٖ يُحِبُّهُمۡ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِينَ أَعِزَّةٍ عَلَى ٱلۡكَٰفِرِينَ يُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوۡمَةَ لَآئِمٖۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ ﴿٥٤﴾ إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُواْ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُمۡ رَٰكِعُونَ ﴿٥٥﴾ وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُواْ فَإِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡغَٰلِبُونَ ﴿٥٦﴾", "w": [["من يرتدّ", "يرجع إلى الكفر بعد إيمانه."], ["أذلّة على المؤمنين", "أرقّاء عليهم، رحماء بهم."], ["أعزّة على الكافرين", "أشدّاء غلاظ عليهم."], ["لومة لائم", "عذل عاذل."]], "m": "تضمّنت الآية خبراً من أخبار الغيب تمّ طبق ما أخبر، فكان آية أنه كلام الله: من يرتدّ منكم عن دينه فسوف يأتي الله بقوم خير منه، يحبهم ويحبونه، رحماء بالمؤمنين، أشدّاء على الكافرين، يجاهدون في سبيل الله ولا يخافون لومة لائم؛ فما إن مات الرسول ﷺ حتى ارتدّت فئات من الأعراب ومنعوا الزكاة، فقاتلهم أبو بكر الصديق مع الصحابة حتى أخضعوهم للإسلام، فكانوا ممن وصف الله. وصحّ أن النبي ﷺ لما تلاها أشار إلى أبي موسى الأشعري وقال: «قوم هذا»، فجاء الأشعريون بعد وفاته وظهرت الآية. ذلك فضل الله يؤتيه من يشاء، والله واسع عليم. ثم طمأن عبادة بن الصامت وعبد الله بن سلام ومن تبرّأ من حلف اليهود: إنما وليّكم الله ورسوله والذين آمنوا، الذين يقيمون الصلاة ويؤتون الزكاة وهم خاشعون متطامنون، ومن يتولّ الله ورسوله والذين آمنوا ينصره الله ويكفه ما أهمّه، فإن حزب الله هم الغالبون.", "h": ["إخبار القرآن الكريم بالغيب وصدقه في ذلك، فكان آية أنه كلام الله.", "فضيلة أبي بكر والصحابة والأشعريين، قوم أبي موسى الأشعري من أهل اليمن.", "فضل حب الله، والتواضع للمؤمنين، وإظهار العزة على الكافرين، وفضل الجهاد في سبيل الله، وقول الحق والثبات عليه، وعدم المبالاة بمن يلوم.", "فضيلة إقام الصلاة وإيتاء الزكاة والخشوع والتواضع.", "ولاية الله ورسوله والمؤمنين الصادقين توجب لصاحبها النصر والغلبة على أعدائه."], "k": "«يحبهم ويحبونه»… ما علامة حبي لله في يومي؟ وهل أنا رحيم بإخواني، لا أخاف في الحق لومة لائم؟"}, {"lbl": "الآيات ٥٧ – ٦٠", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلَّذِينَ ٱتَّخَذُواْ دِينَكُمۡ هُزُوٗا وَلَعِبٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَٱلۡكُفَّارَ أَوۡلِيَآءَۚ وَٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ ﴿٥٧﴾ وَإِذَا نَادَيۡتُمۡ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوٗا وَلَعِبٗاۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ ﴿٥٨﴾ قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ هَلۡ تَنقِمُونَ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ مِن قَبۡلُ وَأَنَّ أَكۡثَرَكُمۡ فَٰسِقُونَ ﴿٥٩﴾ قُلۡ هَلۡ أُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيۡهِ وَجَعَلَ مِنۡهُمُ ٱلۡقِرَدَةَ وَٱلۡخَنَازِيرَ وَعَبَدَ ٱلطَّـٰغُوتَۚ أُوْلَـٰٓئِكَ شَرّٞ مَّكَانٗا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ ﴿٦٠﴾", "w": [["هزواً ولعباً", "الهزء: ما يُستهزأ به ويُسخر منه، واللعب: ما يُلعب به."], ["أوتوا الكتاب", "هم اليهود في هذا السياق."], ["والكفّار", "المشركون والمنافقون."], ["هل تنقمون منا", "ما تنكرون منا وتعيبون علينا."], ["مثوبة", "جزاء."], ["فاسقون", "خارجون عن طاعة الله بالكفر والمعاصي."], ["القردة", "جمع قرد، حيوان مجبول على التقليد والمحاكاة."], ["والخنازير", "جمع خنزير، حيوان خبيث محرّم الأكل."]], "m": "ما زال السياق في تحذير المؤمنين من موالاة أعداء الله: يا أيها الذين آمنوا لا تتخذوا الذين اتخذوا دينكم هزواً ولعباً من اليهود والكفار أولياء، واتقوا الله إن كنتم مؤمنين، فإن حب الله ورسوله يتنافى مع حب أعدائه. ثم ذكر ما يؤكد وجوب معاداتهم: إذا سمعوا الأذان ينادي للصلاة اتخذوه هزواً ولعباً، ذلك بأنهم قوم لا يعقلون، فلو عقلوا لكان النداء إلى الصلاة أطيب ما يسمعون، لأنه نداء إلى الطهر وذكر الله. ثم علّم رسوله أن يقول: يا أهل الكتاب، هل تنكرون منا إلا أن آمنّا بالله وما أنزل إلينا وما أنزل من قبل، وأن أكثركم فاسقون؟ ولما قالوا للنبي ﷺ حين ذكر الإيمان بعيسى: لا نعلم ديناً شراً من دينكم، أنزل الله: قل هل أنبئكم بشرّ من ذلك جزاءً عند الله؟ من لعنه الله وغضب عليه، وجعل منهم القردة والخنازير، وعبد الطاغوت، أولئك شرٌّ مكاناً يوم القيامة، وأضلّ عن سواء السبيل في الدنيا.", "h": ["حرمة اتخاذ اليهود والنصارى والمشركين أولياء، لا سيما أهل الظلم منهم.", "سوء أخلاق اليهود وفساد عقولهم.", "شعور اليهود بفسقهم وبعد ضلالهم جعلهم يعملون على إضلال المسلمين.", "تقرير وجود مسخ في اليهود قردة وخنازير.", "اليهود شرّ الناس مكاناً يوم القيامة، وأضلّ الناس في هذه الدنيا."], "k": "الأذان نداء إلى الطهر وذكر الله… كيف أستقبله: بانشغال، أم بترديد وإجابة؟"}, {"lbl": "الآيات ٦١ – ٦٣", "q": "وَإِذَا جَآءُوكُمۡ قَالُوٓاْ ءَامَنَّا وَقَد دَّخَلُواْ بِٱلۡكُفۡرِ وَهُمۡ قَدۡ خَرَجُواْ بِهِۦۚ وَٱللَّهُ أَعۡلَمُ بِمَا كَانُواْ يَكۡتُمُونَ ﴿٦١﴾ وَتَرَىٰ كَثِيرٗا مِّنۡهُمۡ يُسَٰرِعُونَ فِي ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَعۡمَلُونَ ﴿٦٢﴾ لَوۡلَا يَنۡهَىٰهُمُ ٱلرَّبَّـٰنِيُّونَ وَٱلۡأَحۡبَارُ عَن قَوۡلِهِمُ ٱلۡإِثۡمَ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَصۡنَعُونَ ﴿٦٣﴾", "w": [["يكتمون", "يُضمرون في نفوسهم ويخفونه."], ["في الإثم والعدوان", "الإثم: كل ضارّ وفاسد مما حرّمه الله من اعتقاد أو قول أو عمل، والعدوان: الظلم."], ["السحت", "المال الحرام كالرشوة والربا، وما يأخذونه مقابل تحريف الكلم وتأويله."], ["الربانيون والأحبار", "الربانيون هنا: العبّاد المربّون، والأحبار: العلماء."]], "m": "ما زال السياق في فضح اليهود زيادةً في التنفير من موالاتهم: وإذا جاؤوكم في مجالسكم قالوا آمنّا، وما آمنوا، فقد دخلوا بالكفر وخرجوا به، والله أعلم بما كانوا يكتمون من الكفر والكيد لكم. وترى كثيراً منهم يسارعون في الإثم والعدوان وأكلهم السحت علناً لا يستترون به، لبئس ما كانوا يعملون. ثم أنكر على عبّادهم وعلمائهم سكوتهم عن جرائم عوامّهم مصانعةً ومداهنة: لولا ينهاهم الربانيون والأحبار عن قولهم الإثم، أي الكذب، وأكلهم السحت، لبئس ما كانوا يصنعون، إذ أصبح السكوت المتعمّد لمنافع خاصة صنعةً لهم أتقنوها.", "h": ["وجود منافقين من اليهود على عهد الرسول ﷺ بالمدينة.", "بيان استهتار اليهود وعدم مبالاتهم بارتكاب الجرائم علانية.", "قبح سكوت العلماء على المنكر وإغضائهم عن فاعليه، ولذا قال كثير من السلف: هذه أشدّ آية وأخطرها على العلماء."], "k": "«لولا ينهاهم الربانيون والأحبار»… هل أسكت عن منكر أستطيع أن أنكره بالحكمة، مجاملةً لأحد؟"}, {"lbl": "الآيات ٦٤ – ٦٦", "q": "وَقَالَتِ ٱلۡيَهُودُ يَدُ ٱللَّهِ مَغۡلُولَةٌۚ غُلَّتۡ أَيۡدِيهِمۡ وَلُعِنُواْ بِمَا قَالُواْۘ بَلۡ يَدَاهُ مَبۡسُوطَتَانِ يُنفِقُ كَيۡفَ يَشَآءُۚ وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۚ وَأَلۡقَيۡنَا بَيۡنَهُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ كُلَّمَآ أَوۡقَدُواْ نَارٗا لِّلۡحَرۡبِ أَطۡفَأَهَا ٱللَّهُۚ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادٗاۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ ﴿٦٤﴾ وَلَوۡ أَنَّ أَهۡلَ ٱلۡكِتَٰبِ ءَامَنُواْ وَٱتَّقَوۡاْ لَكَفَّرۡنَا عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأَدۡخَلۡنَٰهُمۡ جَنَّـٰتِ ٱلنَّعِيمِ ﴿٦٥﴾ وَلَوۡ أَنَّهُمۡ أَقَامُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡهِم مِّن رَّبِّهِمۡ لَأَكَلُواْ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ مِّنۡهُمۡ أُمَّةٞ مُّقۡتَصِدَةٞۖ وَكَثِيرٞ مِّنۡهُمۡ سَآءَ مَا يَعۡمَلُونَ ﴿٦٦﴾", "w": [["يد الله مغلولة", "يريدون أنه تعالى ضيّق عليهم الرزق ولم يوسّع عليهم."], ["غُلّت أيديهم", "دعاء عليهم بأن يُحرموا الإنفاق في الخير وفيما ينفعهم."], ["لُعنوا بما قالوا", "طُردوا من رحمة الله بسبب وصفهم الرب تعالى بالبخل."], ["بل يداه مبسوطتان", "لا كما قالوا: ممسكة عن الإنفاق."], ["طغياناً", "تجاوزاً لحد الاعتدال في قولهم الكاذب وعملهم الفاسد."], ["وألقينا بينهم", "بين اليهود والنصارى."], ["أوقدوا ناراً", "نار الفتنة والتحريش والعداوات للحرب."], ["من فوقهم ومن تحت أرجلهم", "كناية عن بسط الرزق عليهم."], ["أمة مقتصدة", "معتدلة، لا غالية مُفرِطة ولا جافية مُفرّطة."]], "m": "يخبر الله عن جرأة اليهود عليه: وقالت اليهود يد الله مغلولة، يريدون أنه أمسك عنهم الرزق، فدعا عليهم: غُلّت أيديهم ولُعنوا بما قالوا، وأكذبهم: بل يداه مبسوطتان ينفق كيف يشاء، كما في الصحيح: «يمين الله ملأى، سحّاء الليل والنهار». ثم سلّى نبيه ﷺ: وليزيدنّ كثيراً منهم ما أُنزل إليك من ربك طغياناً وكفراً، دفعاً للحق وتبريراً لباطلهم، وألقينا بينهم وبين النصارى العداوة والبغضاء إلى يوم القيامة، كلما أوقدوا ناراً للحرب بالتحريش بين الأفراد والشعوب أطفأها الله، فأذلّهم على يد رسوله والمؤمنين، ويسعون في الأرض فساداً، والله لا يحب المفسدين. ثم وعد: ولو أن أهل الكتاب آمنوا واتقوا الكفر والشرك والكبائر لكفّر عنهم سيئاتهم ولأدخلهم جنات النعيم. ولو أنهم أقاموا التوراة والإنجيل وما أُنزل إليهم من ربهم، ومنه القرآن، فآمنوا بعقائدها الصحيحة وعملوا بشرائعها، لأكلوا من فوقهم ومن تحت أرجلهم، ولبسط الله عليهم الرزق. منهم أمة مقتصدة لم تغلُ في عيسى ولم تجفُ، فلما جاء النبي الأمي آمنوا به، كعبد الله بن سلام والنجاشي، وكثير منهم ساء ما يعملون.", "h": ["قبح وصف الله تعالى بما لا يليق بجلاله وكماله.", "ثبوت صفة اليدين لله تعالى، ووجوب الإيمان بها على مراد الله وعلى ما يليق بجلاله.", "تقرير ما هو موجود بين اليهود والنصارى من عداوة وبغضاء، وهو من تدبير الله تعالى.", "سعي اليهود الدائم في الفساد في الأرض، فقد ضربوا البشرية بالمذهب المادي الإلحادي الشيوعي، وضربوها أيضاً بالإباحية ومكائد الماسونية.", "وعد الله لأهل الكتاب لو آمنوا واتقوا لأدخلهم الجنة.", "وعده تعالى لأهل الكتاب ببسط الرزق وسعته لو أقاموا التوراة والإنجيل وما أُنزل إليهم من ربهم، كما حصل للمسلمين طيلة ثلاثة قرون وزيادة، وما زال العرض قائماً لكل الأمم."], "k": "«لأكلوا من فوقهم ومن تحت أرجلهم»… هل أطلب سعة الرزق بإقامة كتاب الله، قبل الأسباب؟"}]$j$::jsonb then 0 else 1 end;
