insert into public.tdb_cards(topic, i, body) select 84, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥١ – ٥٣", "q": "۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوۡلِيَآءَۘ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿٥١﴾ فَتَرَى ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ يُسَٰرِعُونَ فِيهِمۡ يَقُولُونَ نَخۡشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٞۚ فَعَسَى ٱللَّهُ أَن يَأۡتِيَ بِٱلۡفَتۡحِ أَوۡ أَمۡرٖ مِّنۡ عِندِهِۦ فَيُصۡبِحُواْ عَلَىٰ مَآ أَسَرُّواْ فِيٓ أَنفُسِهِمۡ نَٰدِمِينَ ﴿٥٢﴾ وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓاْ أَهَـٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ إِنَّهُمۡ لَمَعَكُمۡۚ حَبِطَتۡ أَعۡمَٰلُهُمۡ فَأَصۡبَحُواْ خَٰسِرِينَ ﴿٥٣﴾", "w": [["آمنوا", "صدّقوا بالله ورسوله ووعد الله ووعيده."], ["أولياء", "توالونهم بالنصرة والمحبة."], ["بعضهم أولياء بعض", "اليهودي ولي أخيه اليهودي، والنصراني ولي أخيه النصراني."], ["الظالمين", "الذين يوالون أعداء الله ورسوله ويتركون موالاة الله ورسوله."], ["مرض", "نفاق وشك وشرك."], ["يسارعون فيهم", "في البقاء على موالاتهم."], ["دائرة", "تدور علينا من جدب أو انتهاء أمر الإسلام."], ["بالفتح", "نصر المؤمنين على الكافرين، كفتح مكة."], ["جهد أيمانهم", "أقصاها وأبلغها."], ["حبطت أعمالهم", "بطلت وفسدت فلم ينتفعوا منها بشيء، لأنها ما كانت لله تعالى."]], "m": "ورد في سبب نزولها أن عبادة بن الصامت الأنصاري وعبد الله بن أُبيّ كان لهما حلفاء من اليهود، فلما أعلن اليهود سوء نياتهم تبرّأ عبادة من حلفائه ورضي بموالاة الله ورسوله والمؤمنين، وأبى ابن أُبيّ ذلك، فنزلت: يا أيها الذين آمنوا لا تتخذوا اليهود والنصارى أولياء، بعضهم أولياء بعض على المسلمين، فكيف تجوز موالاتهم؟ ومن يتولّهم منكم فإنه منهم، لأنه بحكم موالاتهم سيكون حرباً على الله ورسوله والمؤمنين، إن الله لا يهدي القوم الظالمين الذين وضعوا الموالاة في غير محلها. ثم قال لرسوله: فترى الذين في قلوبهم مرض، كابن أُبيّ، يسارعون في موالاتهم، يقولون: نخشى أن تصيبنا دائرة من تقلّب الأحوال فننتفع بأحلافنا، فعسى الله أن يأتي بالفتح، وعسى من الله للتحقيق، أو أمر من عنده فيصبحوا على ما أسرّوا في أنفسهم من النفاق نادمين. ويقول الذين آمنوا عند الفتح، مشيرين إلى المنافقين: أهؤلاء الذين أقسموا بالله جهد أيمانهم إنهم لمعكم؟ حبطت أعمالهم فأصبحوا خاسرين.", "h": ["حرمة موالاة اليهود والنصارى وسائر الكافرين.", "موالاة الكافر على المؤمن تُعتبر ردّة عن الإسلام.", "موالاة الكافرين ناجمة عن ضعف الإيمان، فلذا تؤدي إلى الكفر.", "عاقبة النفاق سيئة، ونهاية الكفر مريرة."], "k": "لمن ولائي ومحبتي ونصرتي؟ وهل يقدّمني ولائي يوم القيامة أم يُخجلني؟"}, {"lbl": "الآيات ٥٤ – ٥٦", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَن يَرۡتَدَّ مِنكُمۡ عَن دِينِهِۦ فَسَوۡفَ يَأۡتِي ٱللَّهُ بِقَوۡمٖ يُحِبُّهُمۡ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِينَ أَعِزَّةٍ عَلَى ٱلۡكَٰفِرِينَ يُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوۡمَةَ لَآئِمٖۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ ﴿٥٤﴾ إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُواْ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُمۡ رَٰكِعُونَ ﴿٥٥﴾ وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُواْ فَإِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡغَٰلِبُونَ ﴿٥٦﴾", "w": [["من يرتدّ", "يرجع إلى الكفر بعد إيمانه."], ["أذلّة على المؤمنين", "أرقّاء عليهم، رحماء بهم."], ["أعزّة على الكافرين", "أشدّاء غلاظ عليهم."], ["لومة لائم", "عذل عاذل."]], "m": "تضمّنت الآية خبراً من أخبار الغيب تمّ طبق ما أخبر، فكان آية أنه كلام الله: من يرتدّ منكم عن دينه فسوف يأتي الله بقوم خير منه، يحبهم ويحبونه، رحماء بالمؤمنين، أشدّاء على الكافرين، يجاهدون في سبيل الله ولا يخافون لومة لائم؛ فما إن مات الرسول ﷺ حتى ارتدّت فئات من الأعراب ومنعوا الزكاة، فقاتلهم أبو بكر الصديق مع الصحابة حتى أخضعوهم للإسلام، فكانوا ممن وصف الله. وصحّ أن النبي ﷺ لما تلاها أشار إلى أبي موسى الأشعري وقال: «قوم هذا»، فجاء الأشعريون بعد وفاته وظهرت الآية. ذلك فضل الله يؤتيه من يشاء، والله واسع عليم. ثم طمأن عبادة بن الصامت وعبد الله بن سلام ومن تبرّأ من حلف اليهود: إنما وليّكم الله ورسوله والذين آمنوا، الذين يقيمون الصلاة ويؤتون الزكاة وهم خاشعون متطامنون، ومن يتولّ الله ورسوله والذين آمنوا ينصره الله ويكفه ما أهمّه، فإن حزب الله هم الغالبون.", "h": ["إخبار القرآن الكريم بالغيب وصدقه في ذلك، فكان آية أنه كلام الله.", "فضيلة أبي بكر والصحابة والأشعريين، قوم أبي موسى الأشعري من أهل اليمن.", "فضل حب الله، والتواضع للمؤمنين، وإظهار العزة على الكافرين، وفضل الجهاد في سبيل الله، وقول الحق والثبات عليه، وعدم المبالاة بمن يلوم.", "فضيلة إقام الصلاة وإيتاء الزكاة والخشوع والتواضع.", "ولاية الله ورسوله والمؤمنين الصادقين توجب لصاحبها النصر والغلبة على أعدائه."], "k": "«يحبهم ويحبونه»… ما علامة حبي لله في يومي؟ وهل أنا رحيم بإخواني، لا أخاف في الحق لومة لائم؟"}, {"lbl": "الآيات ٥٧ – ٦٠", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلَّذِينَ ٱتَّخَذُواْ دِينَكُمۡ هُزُوٗا وَلَعِبٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَٱلۡكُفَّارَ أَوۡلِيَآءَۚ وَٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ ﴿٥٧﴾ وَإِذَا نَادَيۡتُمۡ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوٗا وَلَعِبٗاۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ ﴿٥٨﴾ قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ هَلۡ تَنقِمُونَ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ مِن قَبۡلُ وَأَنَّ أَكۡثَرَكُمۡ فَٰسِقُونَ ﴿٥٩﴾ قُلۡ هَلۡ أُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيۡهِ وَجَعَلَ مِنۡهُمُ ٱلۡقِرَدَةَ وَٱلۡخَنَازِيرَ وَعَبَدَ ٱلطَّـٰغُوتَۚ أُوْلَـٰٓئِكَ شَرّٞ مَّكَانٗا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ ﴿٦٠﴾", "w": [["هزواً ولعباً", "الهزء: ما يُستهزأ به ويُسخر منه، واللعب: ما يُلعب به."], ["أوتوا الكتاب", "هم اليهود في هذا السياق."], ["والكفّار", "المشركون والمنافقون."], ["هل تنقمون منا", "ما تنكرون منا وتعيبون علينا."], ["مثوبة", "جزاء."], ["فاسقون", "خارجون عن طاعة الله بالكفر والمعاصي."], ["القردة", "جمع قرد، حيوان مجبول على التقليد والمحاكاة."], ["والخنازير", "جمع خنزير، حيوان خبيث محرّم الأكل."]], "m": "ما زال السياق في تحذير المؤمنين من موالاة أعداء الله: يا أيها الذين آمنوا لا تتخذوا الذين اتخذوا دينكم هزواً ولعباً من اليهود والكفار أولياء، واتقوا الله إن كنتم مؤمنين، فإن حب الله ورسوله يتنافى مع حب أعدائه. ثم ذكر ما يؤكد وجوب معاداتهم: إذا سمعوا الأذان ينادي للصلاة اتخذوه هزواً ولعباً، ذلك بأنهم قوم لا يعقلون، فلو عقلوا لكان النداء إلى الصلاة أطيب ما يسمعون، لأنه نداء إلى الطهر وذكر الله. ثم علّم رسوله أن يقول: يا أهل الكتاب، هل تنكرون منا إلا أن آمنّا بالله وما أنزل إلينا وما أنزل من قبل، وأن أكثركم فاسقون؟ ولما قالوا للنبي ﷺ حين ذكر الإيمان بعيسى: لا نعلم ديناً شراً من دينكم، أنزل الله: قل هل أنبئكم بشرّ من ذلك جزاءً عند الله؟ من لعنه الله وغضب عليه، وجعل منهم القردة والخنازير، وعبد الطاغوت، أولئك شرٌّ مكاناً يوم القيامة، وأضلّ عن سواء السبيل في الدنيا.", "h": ["حرمة اتخاذ اليهود والنصارى والمشركين أولياء، لا سيما أهل الظلم منهم.", "سوء أخلاق اليهود وفساد عقولهم.", "شعور اليهود بفسقهم وبعد ضلالهم جعلهم يعملون على إضلال المسلمين.", "تقرير وجود مسخ في اليهود قردة وخنازير.", "اليهود شرّ الناس مكاناً يوم القيامة، وأضلّ الناس في هذه الدنيا."], "k": "الأذان نداء إلى الطهر وذكر الله… كيف أستقبله: بانشغال، أم بترديد وإجابة؟"}, {"lbl": "الآيات ٦١ – ٦٣", "q": "وَإِذَا جَآءُوكُمۡ قَالُوٓاْ ءَامَنَّا وَقَد دَّخَلُواْ بِٱلۡكُفۡرِ وَهُمۡ قَدۡ خَرَجُواْ بِهِۦۚ وَٱللَّهُ أَعۡلَمُ بِمَا كَانُواْ يَكۡتُمُونَ ﴿٦١﴾ وَتَرَىٰ كَثِيرٗا مِّنۡهُمۡ يُسَٰرِعُونَ فِي ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَعۡمَلُونَ ﴿٦٢﴾ لَوۡلَا يَنۡهَىٰهُمُ ٱلرَّبَّـٰنِيُّونَ وَٱلۡأَحۡبَارُ عَن قَوۡلِهِمُ ٱلۡإِثۡمَ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَصۡنَعُونَ ﴿٦٣﴾", "w": [["يكتمون", "يُضمرون في نفوسهم ويخفونه."], ["في الإثم والعدوان", "الإثم: كل ضارّ وفاسد مما حرّمه الله من اعتقاد أو قول أو عمل، والعدوان: الظلم."], ["السحت", "المال الحرام كالرشوة والربا، وما يأخذونه مقابل تحريف الكلم وتأويله."], ["الربانيون والأحبار", "الربانيون هنا: العبّاد المربّون، والأحبار: العلماء."]], "m": "ما زال السياق في فضح اليهود زيادةً في التنفير من موالاتهم: وإذا جاؤوكم في مجالسكم قالوا آمنّا، وما آمنوا، فقد دخلوا بالكفر وخرجوا به، والله أعلم بما كانوا يكتمون من الكفر والكيد لكم. وترى كثيراً منهم يسارعون في الإثم والعدوان وأكلهم السحت علناً لا يستترون به، لبئس ما كانوا يعملون. ثم أنكر على عبّادهم وعلمائهم سكوتهم عن جرائم عوامّهم مصانعةً ومداهنة: لولا ينهاهم الربانيون والأحبار عن قولهم الإثم، أي الكذب، وأكلهم السحت، لبئس ما كانوا يصنعون، إذ أصبح السكوت المتعمّد لمنافع خاصة صنعةً لهم أتقنوها.", "h": ["وجود منافقين من اليهود على عهد الرسول ﷺ بالمدينة.", "بيان استهتار اليهود وعدم مبالاتهم بارتكاب الجرائم علانية.", "قبح سكوت العلماء على المنكر وإغضائهم عن فاعليه، ولذا قال كثير من السلف: هذه أشدّ آية وأخطرها على العلماء."], "k": "«لولا ينهاهم الربانيون والأحبار»… هل أسكت عن منكر أستطيع أن أنكره بالحكمة، مجاملةً لأحد؟"}, {"lbl": "الآيات ٦٤ – ٦٦", "q": "وَقَالَتِ ٱلۡيَهُودُ يَدُ ٱللَّهِ مَغۡلُولَةٌۚ غُلَّتۡ أَيۡدِيهِمۡ وَلُعِنُواْ بِمَا قَالُواْۘ بَلۡ يَدَاهُ مَبۡسُوطَتَانِ يُنفِقُ كَيۡفَ يَشَآءُۚ وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۚ وَأَلۡقَيۡنَا بَيۡنَهُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ كُلَّمَآ أَوۡقَدُواْ نَارٗا لِّلۡحَرۡبِ أَطۡفَأَهَا ٱللَّهُۚ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادٗاۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ ﴿٦٤﴾ وَلَوۡ أَنَّ أَهۡلَ ٱلۡكِتَٰبِ ءَامَنُواْ وَٱتَّقَوۡاْ لَكَفَّرۡنَا عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأَدۡخَلۡنَٰهُمۡ جَنَّـٰتِ ٱلنَّعِيمِ ﴿٦٥﴾ وَلَوۡ أَنَّهُمۡ أَقَامُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡهِم مِّن رَّبِّهِمۡ لَأَكَلُواْ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ مِّنۡهُمۡ أُمَّةٞ مُّقۡتَصِدَةٞۖ وَكَثِيرٞ مِّنۡهُمۡ سَآءَ مَا يَعۡمَلُونَ ﴿٦٦﴾", "w": [["يد الله مغلولة", "يريدون أنه تعالى ضيّق عليهم الرزق ولم يوسّع عليهم."], ["غُلّت أيديهم", "دعاء عليهم بأن يُحرموا الإنفاق في الخير وفيما ينفعهم."], ["لُعنوا بما قالوا", "طُردوا من رحمة الله بسبب وصفهم الرب تعالى بالبخل."], ["بل يداه مبسوطتان", "لا كما قالوا: ممسكة عن الإنفاق."], ["طغياناً", "تجاوزاً لحد الاعتدال في قولهم الكاذب وعملهم الفاسد."], ["وألقينا بينهم", "بين اليهود والنصارى."], ["أوقدوا ناراً", "نار الفتنة والتحريش والعداوات للحرب."], ["من فوقهم ومن تحت أرجلهم", "كناية عن بسط الرزق عليهم."], ["أمة مقتصدة", "معتدلة، لا غالية مُفرِطة ولا جافية مُفرّطة."]], "m": "يخبر الله عن جرأة اليهود عليه: وقالت اليهود يد الله مغلولة، يريدون أنه أمسك عنهم الرزق، فدعا عليهم: غُلّت أيديهم ولُعنوا بما قالوا، وأكذبهم: بل يداه مبسوطتان ينفق كيف يشاء، كما في الصحيح: «يمين الله ملأى، سحّاء الليل والنهار». ثم سلّى نبيه ﷺ: وليزيدنّ كثيراً منهم ما أُنزل إليك من ربك طغياناً وكفراً، دفعاً للحق وتبريراً لباطلهم، وألقينا بينهم وبين النصارى العداوة والبغضاء إلى يوم القيامة، كلما أوقدوا ناراً للحرب بالتحريش بين الأفراد والشعوب أطفأها الله، فأذلّهم على يد رسوله والمؤمنين، ويسعون في الأرض فساداً، والله لا يحب المفسدين. ثم وعد: ولو أن أهل الكتاب آمنوا واتقوا الكفر والشرك والكبائر لكفّر عنهم سيئاتهم ولأدخلهم جنات النعيم. ولو أنهم أقاموا التوراة والإنجيل وما أُنزل إليهم من ربهم، ومنه القرآن، فآمنوا بعقائدها الصحيحة وعملوا بشرائعها، لأكلوا من فوقهم ومن تحت أرجلهم، ولبسط الله عليهم الرزق. منهم أمة مقتصدة لم تغلُ في عيسى ولم تجفُ، فلما جاء النبي الأمي آمنوا به، كعبد الله بن سلام والنجاشي، وكثير منهم ساء ما يعملون.", "h": ["قبح وصف الله تعالى بما لا يليق بجلاله وكماله.", "ثبوت صفة اليدين لله تعالى، ووجوب الإيمان بها على مراد الله وعلى ما يليق بجلاله.", "تقرير ما هو موجود بين اليهود والنصارى من عداوة وبغضاء، وهو من تدبير الله تعالى.", "سعي اليهود الدائم في الفساد في الأرض، فقد ضربوا البشرية بالمذهب المادي الإلحادي الشيوعي، وضربوها أيضاً بالإباحية ومكائد الماسونية.", "وعد الله لأهل الكتاب لو آمنوا واتقوا لأدخلهم الجنة.", "وعده تعالى لأهل الكتاب ببسط الرزق وسعته لو أقاموا التوراة والإنجيل وما أُنزل إليهم من ربهم، كما حصل للمسلمين طيلة ثلاثة قرون وزيادة، وما زال العرض قائماً لكل الأمم."], "k": "«لأكلوا من فوقهم ومن تحت أرجلهم»… هل أطلب سعة الرزق بإقامة كتاب الله، قبل الأسباب؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;